import{_ as s,o as t,c as i,a0 as o}from"./chunks/framework.CR-yHhk1.js";const k=JSON.parse('{"title":"The sepia serve wire","description":"","frontmatter":{},"headers":[],"relativePath":"reference/serve-wire.md","filePath":"reference/serve-wire.md"}'),d={name:"reference/serve-wire.md"};function a(n,e,c,r,h,l){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="the-sepia-serve-wire" tabindex="-1">The <code>sepia serve</code> wire <a class="header-anchor" href="#the-sepia-serve-wire" aria-label="Permalink to &quot;The `sepia serve` wire&quot;">​</a></h1><p><code>sepia serve</code> exposes the local session plane as ndjson JSON-RPC over stdio — the same framing <code>sepia-driver-*</code> binaries speak, described in <a href="./protocol.html">the driver protocol</a>. One JSON object per line, requests and responses interleaved; <code>session.event</code> notifications arrive unsolicited after <code>sessions.subscribe</code>, <code>node.event</code> notifications after <code>events.subscribe</code>.</p><h2 id="handshake" tabindex="-1">Handshake <a class="header-anchor" href="#handshake" aria-label="Permalink to &quot;Handshake&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;jsonrpc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;method&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;manifest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;params&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{}}</span></span></code></pre></div><p>The manifest reports <code>name</code>, <code>version</code>, <code>protocol</code> (the wire version — bumped on breaking changes), <code>node</code> (<code>{id, name}</code> — the machine identity minted at <code>$SEPIA_HOME/node.json</code>), <code>config</code>, and <code>methods</code>. Orchestrators should check <code>protocol</code> before issuing calls; peregrin&#39;s <code>peregrin-session</code> crate refuses to bind a mismatched service.</p><p><code>config</code> is the plane&#39;s resolved lifecycle tuning — what the <code>SEPIA_*</code> env and defaults actually produced, so a spawner can verify its env took effect on the child:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;idleTtlMs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">600000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;sweepMs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;historyLimit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;probeIdleMs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>idleTtlMs</code> is <code>null</code> when the idle sweep is disabled (a zero TTL); <code>probeIdleMs</code> is the resolved lock-probe pool TTL — the <code>probe_idle</code> override, or ten lock TTLs floored at 60s.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Plane call</th></tr></thead><tbody><tr><td><code>manifest</code></td><td>Service manifest + method list</td></tr><tr><td><code>agents.list</code></td><td>Registered agents + capabilities</td></tr><tr><td><code>sessions.list</code></td><td><code>list_sessions</code> (<code>withLocks</code> param probes live lock state)</td></tr><tr><td><code>sessions.get</code></td><td>Full session IR (<code>id</code>, optional <code>agent</code>)</td></tr><tr><td><code>sessions.summary</code></td><td>Metadata-only session</td></tr><tr><td><code>sessions.export</code></td><td>Full session IR wrapped as <code>{session}</code> — the transfer bundle (<code>id</code>, <code>agent?</code>)</td></tr><tr><td><code>sessions.import</code></td><td>Write IR into an agent&#39;s store via <code>session.save</code> (<code>agent</code>, <code>session</code>, <code>id?</code>, <code>cwd?</code>, <code>title?</code>, <code>model?</code>) → <code>{id, agentId}</code>; mints a fresh id unless <code>id</code> is passed</td></tr><tr><td><code>sessions.convert</code></td><td>Node-local copy of a stored session into another agent&#39;s store (<code>id</code>, <code>agent</code>, <code>from?</code>) → <code>{sessionId, agentId}</code></td></tr><tr><td><code>sessions.history</code></td><td>Paginated history (<code>id</code>, <code>limit</code>, <code>before</code>)</td></tr><tr><td><code>sessions.attach</code></td><td>Attach (<code>id</code>, <code>takeover</code>, <code>model</code>, <code>fallbacks</code>, <code>permissions</code>)</td></tr><tr><td><code>sessions.detach</code></td><td>Release a held session</td></tr><tr><td><code>sessions.create</code></td><td>New session (<code>cwd</code>, <code>agent</code>, <code>title</code>, <code>model</code>, <code>fallbacks</code>, <code>permissions</code>)</td></tr><tr><td><code>sessions.prompt</code></td><td>Send a turn (<code>id</code>, <code>parts</code>, <code>agent</code>) — resolves when the agent finishes the turn, returns <code>null</code></td></tr><tr><td><code>sessions.prompt_wait</code></td><td>Prompt + await the turn&#39;s terminal state (<code>id</code>, <code>parts</code>, <code>agent?</code>, <code>timeoutMs?</code>) → <code>PromptWaitResult</code></td></tr><tr><td><code>sessions.cancel</code></td><td>Cancel a running turn</td></tr><tr><td><code>sessions.permission</code></td><td>Resolve a permission request (<code>id</code>, <code>request</code>, <code>option</code>)</td></tr><tr><td><code>sessions.set_mode</code></td><td>Switch the agent mode (<code>id</code>, <code>mode</code>, <code>agent?</code>) — <code>session/set_mode</code></td></tr><tr><td><code>sessions.set_permission_policy</code></td><td>Set the permission policy (<code>id</code>, <code>permissions</code>, <code>agent?</code>)</td></tr><tr><td><code>sessions.delete</code></td><td>Delete from the owning store</td></tr><tr><td><code>sessions.patch_meta</code></td><td>Meta overlay patch (<code>id</code>, <code>patch</code>: <code>title</code>/<code>pinned</code>/<code>archived</code>/<code>projectIds</code>/<code>model</code>)</td></tr><tr><td><code>config.list</code></td><td>Per-agent config inventory (<code>agent?</code>, <code>dir?</code>) → <code>[{agent, counts}]</code> for every <code>AgentConfig</code>-capable driver; a failing driver yields <code>{agent, error}</code></td></tr><tr><td><code>config.get</code></td><td>Agent-config IR (<code>agent</code>, <code>dir?</code>) via the driver&#39;s <code>config.read</code> — the serialized <code>AgentConfig</code> (per-item + config <code>metadata</code> included)</td></tr><tr><td><code>config.import</code></td><td>Install a config IR payload (<code>agent</code>, <code>dir?</code>, <code>config</code>) via <code>config.write</code> → <code>{actions}</code> — <code>config</code> accepts the <code>config export</code> JSON or a serialized <code>AgentConfig</code></td></tr><tr><td><code>sessions.restore</code></td><td>Restore rewindable files (<code>id</code>, <code>request</code>)</td></tr><tr><td><code>sessions.rewind</code></td><td>Rewind messages/history (<code>id</code>, <code>request</code>)</td></tr><tr><td><code>sessions.subscribe</code></td><td>Subscribe (<code>id</code>, <code>keepAlive?</code> — <code>false</code> = non-pinning watch) → <code>session.event</code> notifications</td></tr><tr><td><code>events.subscribe</code></td><td>Node-wide feed → <code>node.event</code> notifications</td></tr><tr><td><code>shutdown</code></td><td>Close the plane, exit 0</td></tr></tbody></table><h2 id="sessions-prompt-wait" tabindex="-1"><code>sessions.prompt_wait</code> <a class="header-anchor" href="#sessions-prompt-wait" aria-label="Permalink to &quot;`sessions.prompt_wait`&quot;">​</a></h2><p>The blocking counterpart of <code>sessions.prompt</code> — the primitive an orchestrator uses to drive an agent to completion without subscribing:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;jsonrpc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;method&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sessions.prompt_wait&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;params&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;session&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;parts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:[{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;fix the build&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}],</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;timeoutMs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span></code></pre></div><p>Params mirror <code>sessions.prompt</code> plus <code>timeoutMs</code> (milliseconds; <code>0</code> or absent waits until the turn settles, bounded only by agent liveness). The result is the settled-turn report:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;sessionId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;agentId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;devin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;stopReason&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;end_turn&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;eventCount&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;laggedEvents&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;durationMs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8421.3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;timedOut&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><code>stopReason</code> — the agent&#39;s terminal reason (<code>end_turn</code>, <code>cancelled</code>, <code>max_tokens</code>, <code>refusal</code>, …); absent when the turn errored before the agent answered or the wait timed out mid-flight.</li><li><code>text</code> — the assistant text observed during the turn (concatenated <code>textMessageContent</code> deltas); <code>laggedEvents</code> counts broadcast batches the waiter dropped, so a nonzero value means <code>text</code> may be partial.</li><li><code>timedOut</code> — the timeout elapsed before the turn settled. The wait sends <code>session/cancel</code> and gives the turn a short settle window; a turn that outlives it keeps running in the background (its events still stream to subscribers) and <code>stopReason</code> stays absent.</li><li><code>error</code> — present on turn-level failure (agent died mid-turn, ACP error); pre-dispatch rejections (<code>invalid</code>, <code>busy</code>, …) still come back as JSON-RPC errors.</li></ul><p>Requests dispatch concurrently — a <code>prompt_wait</code> (or a long <code>sessions.prompt</code>) in flight does not starve <code>sessions.cancel</code>, <code>sessions.permission</code>, or the subscribe verbs. Responses are id-correlated; completion order is not guaranteed.</p><h2 id="permission-policy" tabindex="-1">Permission policy <a class="header-anchor" href="#permission-policy" aria-label="Permalink to &quot;Permission policy&quot;">​</a></h2><p>Agents gate tool use behind ACP <code>session/request_permission</code> — an unattended <code>prompt_wait</code> deadlocks when nothing answers. Each live session carries a <code>PermissionPolicy</code>, default <code>ask</code> (the request broadcasts as an <code>acp:permission_request</code> custom event and waits for <code>sessions.permission</code>). Set it at create/attach time with the <code>permissions</code> param, or switch it live with <code>sessions.set_permission_policy</code>; both accept:</p><ul><li><code>&quot;ask&quot;</code> — broadcast only, manual answering (the default).</li><li><code>&quot;allow_all&quot;</code> — auto-select the best allow option (<code>allow_once</code> preferred, then <code>allow_always</code>, then any <code>allow*</code> kind).</li><li><code>&quot;deny_all&quot;</code> — auto-select the best reject option (<code>reject_once</code>, <code>reject_always</code>, <code>reject*</code>), else the cancelled outcome.</li><li><code>{&quot;rules&quot;: [{&quot;kind&quot;: &quot;execute&quot;, &quot;allow&quot;: false}, …]}</code> — first matching rule decides on the tool-call <code>kind</code> (<code>execute</code>, <code>edit</code>, <code>read</code>, …; a rule without <code>kind</code> matches everything); unmatched requests fall back to <code>ask</code>.</li></ul><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;jsonrpc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;method&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sessions.set_permission_policy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;params&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;session&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;permissions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;rules&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:[{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;execute&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;allow&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;allow&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}]}}}</span></span></code></pre></div><p>The request event still broadcasts under every policy — subscribers observe asks the policy auto-settled. With no matching option kind the plane sends the cancelled outcome rather than guessing an option. <code>create</code>/<code>attach</code> echo the applied policy as <code>permissions</code> in their result (<code>&quot;ask&quot;</code> when none was given or the attach was read-only).</p><h2 id="event-streams" tabindex="-1">Event streams <a class="header-anchor" href="#event-streams" aria-label="Permalink to &quot;Event streams&quot;">​</a></h2><p><code>sessions.subscribe</code> returns <code>{subscribed, sessionId}</code> and forwards the session&#39;s translated frames as <code>session.event</code> notifications — <code>{sessionId, events: [SessionEvent…]}</code>. A repeat subscribe on the same session spawns a second forwarder: notifications duplicate, they are not deduped. If the receiver falls behind the 512-event buffer, a <code>{sessionId, events: [], lagged: n}</code> marker reports the dropped-batch count.</p><p>A subscriber counts as a <em>listener</em> for idle tracking: while one is attached the session never idle-detaches, so its agent subprocess stays alive. Pass <code>&quot;keepAlive&quot;: false</code> for the non-pinning watch — the same <code>session.event</code> stream, but the session still idle-detaches on <code>idleTtlMs</code> and the stream closes with it. Background consumers (orchestrator busy-tracking, log mirrors, one-shot <code>prompt_wait</code>-style callers) should use it; an interactive viewer that wants the session kept warm keeps the default.</p><p><code>events.subscribe</code> returns <code>{subscribed, live}</code> — <code>live</code> is the list of session ids attached at subscribe time — and streams <code>node.event</code> notifications carrying lifecycle markers plus every live session&#39;s events. One subscription covers the whole node; a racing attach can appear in both <code>live</code> and the stream, so dedup by <code>sessionId</code>. The <code>type</code> field discriminates:</p><table tabindex="0"><thead><tr><th><code>type</code></th><th>Payload</th></tr></thead><tbody><tr><td><code>attached</code></td><td><code>{sessionId, agentId}</code> — an existing store session went live</td></tr><tr><td><code>created</code></td><td><code>{sessionId, agentId, cwd}</code> — a fresh session was created live</td></tr><tr><td><code>detached</code></td><td><code>{sessionId, agentId, reason}</code> — left the live map; <code>reason</code> is <code>explicit</code>, <code>idle</code> (the sweep retired it), <code>deleted</code>, <code>rewind</code>, or <code>shutdown</code>. Always the session&#39;s last event on the feed</td></tr><tr><td><code>deleted</code></td><td><code>{sessionId, agentId}</code> — the store row was deleted through its agent</td></tr><tr><td><code>sessionEvents</code></td><td><code>{sessionId, events: [SessionEvent…]}</code> — the same batches <code>sessions.subscribe</code> forwards; <code>runStarted</code>/<code>runFinished</code> mark the busy transitions</td></tr><tr><td><code>lagged</code></td><td><code>{sessionId, count}</code> — <code>sessionId</code> <code>null</code> means the node feed overflowed for this receiver</td></tr></tbody></table><p>Markers mirror live-map membership exactly: a read-only attach or a failed load emits nothing.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p>Failures come back as JSON-RPC errors with <code>data.code</code> matching the plane&#39;s <code>ControlErrorCode</code> (<code>not_found</code>, <code>locked</code>, <code>invalid_params</code>, <code>internal</code>, …) and <code>data.cause</code> carrying the underlying store/driver message. <code>sessions.import</code> answers <code>invalid</code> on a malformed <code>session</code> payload; <code>sessions.convert</code> takes <code>{id, agent, from?}</code> — it reads the session from the store by id (<code>not_found</code> when absent) and answers <code>unknown_agent</code> when no <code>SessionWrite</code> driver exists for <code>agent</code>. <code>config.get</code>/<code>config.import</code>/<code>config.list</code> answer <code>unknown_agent</code> when <code>agent</code> is absent or its driver lacks the <code>AgentConfig</code> capability; <code>config.import</code> answers <code>invalid</code> on a malformed <code>config</code> payload. <code>dir</code> is the config root the driver&#39;s adapter expects — <code>.claude</code>/<code>.cursor</code>/devin config dirs, or a Cline <em>workspace root</em>; absent, the driver resolves its own default (<code>SEPIA_*_DIR</code> envs, user dir, or the driver&#39;s cwd for Cline). The meta verb (<code>sessions.patch_meta</code>) answers <code>invalid</code> on a plane built without a meta store. A spawner that respawns the process should treat a dead child as retryable for idempotent reads; peregrin respawns once per call.</p><p>Session rows in <code>sessions.list</code> carry the meta overlay merged in (<code>pinned</code>, <code>archived</code>, <code>projectIds</code>, <code>spans</code>, title override) plus pending rows for sessions only the overlay knows about — created through <code>sessions.create</code> but never flushed to the agent&#39;s store. <code>sessions.patch_meta</code>&#39;s <code>model</code> field takes <code>null</code> to clear the stored spawn preference (applied on the next <code>sessions.attach</code>).</p><h2 id="discovery-and-environment" tabindex="-1">Discovery and environment <a class="header-anchor" href="#discovery-and-environment" aria-label="Permalink to &quot;Discovery and environment&quot;">​</a></h2><p>Driver discovery and all <code>SEPIA_*</code> env vars apply to the <code>sepia serve</code> child, not the spawner — set them in its environment (<code>SEPIA_DRIVER_DIR</code>, <code>SEPIA_CLAUDE_DIR</code>, <code>SEPIA_CLINE_DIR</code>, <code>SEPIA_DEVIN_DB</code>, lock TTLs). The authoritative list is <code>crates/sepia-host</code> + each driver&#39;s binary source.</p>',33)])])}const u=s(d,[["render",a]]);export{k as __pageData,u as default};
